import { parseBoardCode } from './board-code.ts';
import { createGame } from './state.ts';
import type { GameState } from './state.ts';
import { activateCard, advanceGame } from './transitions.ts';
import { exactKeys, integer, isObject, parseJson } from './validation.ts';

export const REPLAY_VERSION = 1;
export const REPLAY_BYTES = 1048576;
export const MAX_ACTIONS = 10000;

export function replayGame(text: string): GameState | null {
  const value = parseJson(text, REPLAY_BYTES);
  if (!isObject(value) || !exactKeys(value, ['version', 'boardCode', 'actions', 'endMs'])
    || value.version !== REPLAY_VERSION || typeof value.boardCode !== 'string'
    || !parseBoardCode(value.boardCode) || !Array.isArray(value.actions)
    || value.actions.length > MAX_ACTIONS || !integer(value.endMs)) return null;
  let game = createGame(value.boardCode);
  let previousMs = 0;
  for (const action of value.actions) {
    if (!isObject(action) || !exactKeys(action, ['atMs', 'index'])
      || !integer(action.atMs) || action.atMs < previousMs || action.atMs > value.endMs
      || !integer(action.index, game.board.deck.length - 1)) return null;
    game = advanceGame(game, action.atMs - previousMs);
    game = activateCard(game, action.index);
    previousMs = action.atMs;
  }
  return advanceGame(game, value.endMs - previousMs);
}

/work/src/game/state.ts.content:
import { generateBoard } from './board-code.ts';
import type { Board } from './board-code.ts';

export const KIND = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export const MISMATCH_MS = 800;
export const MAX_MOVES = 999999;
export const MAX_ELAPSED_MS = 359999999;
export type Selection =
  | { readonly kind: typeof KIND.closed }
  | { readonly kind: typeof KIND.one; readonly index: number }
  | { readonly kind: typeof KIND.mismatch; readonly first: number;
      readonly second: number; readonly remainingMs: number };

export interface GameState {
  readonly board: Board;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState {
  return { board: generateBoard(boardCode), matched: [], selection: { kind: KIND.closed },
    moves: 0, elapsedMs: 0, started: false };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

export function isRevealed(state: GameState, index: number): boolean {
  if (state.matched.includes(index)) return true;
  switch (state.selection.kind) {
    case KIND.closed: return false;
    case KIND.one: return state.selection.index === index;
    case KIND.mismatch: return state.selection.first === index || state.selection.second === index;
  }
}

export function formatTime(milliseconds: number): string {
  const seconds = Math.floor(milliseconds / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}

